verus! {
    use vstd::prelude::*;

    // ======================================================
    // Specification of `copy`
    // ======================================================
    //
    //     Given any Vec<i8> `arr`, returns a fresh Vec<i8> `result`
    //     such that
    //       1) result.len() == arr.len()
    //       2) ∀ i < arr.len(): result[i] == arr[i]
    //
    // No preconditions are needed (arr may be any finite Vec<i8>).
    // The function clearly terminates because the while‐loop decreases.
    // ======================================================

    fn copy(arr: &Vec<i8>) -> Vec<i8>
        // no requires: arr can be any Vec<i8>
        ensures |result: &Vec<i8>|
            result.len() == arr.len()
            && forall |i: nat|
                  i < arr.len() ==>
                  result[i] == arr[i]
    {
        // We build up the copy element by element
        let mut result: Vec<i8> = Vec::new();
        let mut i: usize = 0;

        // ----------------------------------------------------------------
        // Loop invariant (+ decreases) needed to prove
        //    1) we make progress (termination)
        //    2) correctness on all indices < i
        // ----------------------------------------------------------------
        while i < arr.len()
            invariant
                // (a) i never exceeds arr.len()
                i <= arr.len()
            invariant
                // (b) result so far has exactly i elements
                result.len() == i
            invariant
                // (c) for each j < i, result[j] == arr[j]
                forall |j: nat|
                    j < i ==>
                    result[j] == arr[j]
            decreases
                // ensures termination: the measure arr.len() - i shrinks
                arr.len() - i
        {
            // ----------------------------------------------------------------
            // supporting assertions that help the verifier discharge
            // the loop‐body proof:
            //   – arr[i] is safe to read
            //   – after push, result[i] == arr[i]
            // ----------------------------------------------------------------
            assert(i < arr.len());
            let x: i8 = arr[i];          // read the i‐th element
            result.push(x);              // append it to the result
            assert(result[i] == arr[i]); // now the invariant (c) still holds
            i += 1;
        }

        // At this point i == arr.len(), so by (b) result.len() == arr.len(),
        // and by (c) ∀ j < arr.len(): result[j] == arr[j].
        result
    }
}